use concir_sync::Semaphore;
use std::sync::Arc;
use std::thread;

fn main() {
    let s = Semaphore::new(2);

    let mut handles = Vec::new();

    let s1 = Arc::clone(&s);
    handles.push(thread::spawn(move || {
        w1(s1);
    }));

    let s2 = Arc::clone(&s);
    handles.push(thread::spawn(move || {
        w2(s2);
    }));

    let s3 = Arc::clone(&s);
    handles.push(thread::spawn(move || {
        w3(s3);
    }));

    for h in handles {
        h.join().unwrap();
    }

    println!("DONE done=1");
}

fn w1(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // work
    permit.release();
}

fn w2(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // work
    permit.release();
}

fn w3(s: Arc<Semaphore>) {
    let permit = s.acquire();
    // work
    permit.release();
}
